<!doctype html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#263e38;margin:15px}h1{font-size:18px;margin:0 0 7px}p{color:#76867d;line-height:1.6}.meta{border-bottom:2px solid #08753f;padding-bottom:16px;margin-bottom:20px}.report-crest{float:left;width:49px;height:59px;object-fit:contain;margin-right:16px}.institution{font-size:12px;font-weight:bold;letter-spacing:1px;color:#244a31;margin:0 0 5px}.meta h1{padding-top:2px}.meta .stamp{clear:both;padding-top:8px;border-top:1px solid #e7dba5;margin-top:12px}.stats{margin-bottom:20px;font-size:11px}.stats strong{color:#08753f}table{width:100%;border-collapse:collapse}th{background:#08753f;color:white;text-align:left;padding:9px 7px;font-size:8px}td{padding:9px 7px;border-bottom:1px solid #e2eae5}tr:nth-child(even){background:#f7faf8}.total{background:#eaf5ef;font-weight:bold}.footer{margin-top:22px;font-size:8px}.stamp{text-align:right;color:#8e9c94;font-size:8px}</style></head><body><div class="meta"><img class="report-crest" src="{{ public_path('images/logo-banggai.png') }}" alt="Lambang Kabupaten Banggai"><div class="institution">{{ mb_strtoupper(config('app.institution')) }}</div><h1>Laporan Pelayanan Keluarga Berencana</h1><p>{{ config('app.name') }} · {{ config('app.institution') }} · {{ $scope }}</p><div class="stamp">Dicetak: {{ now()->translatedFormat('d F Y H:i') }} WIB · Oleh: {{ auth()->user()->name }}</div></div><div class="stats">Peserta unik terlayani: <strong>{{ $summary['unique'] }}</strong> &nbsp;&nbsp; Peserta baru: <strong>{{ $summary['new'] }}</strong> &nbsp;&nbsp; Jumlah pelayanan: <strong>{{ $summary['visits'] }}</strong>@if(!$scoped)&nbsp;&nbsp; Target: <strong>{{ $summary['target']??'Belum diatur' }}</strong> &nbsp;&nbsp; Capaian: <strong>{{ $summary['percentage']!==null?$summary['percentage'].'%':'—' }}</strong>@endif</div><table><thead><tr><th>Bulan</th><th>Peserta unik</th><th>Baru</th><th>Pelayanan</th>@foreach(\App\Models\Service::METHODS as $method)<th>{{ $method }}</th>@endforeach</tr></thead><tbody>@foreach($rows as $row)<tr><td>{{ $row['label'] }}</td><td>{{ $row['unique'] }}</td><td>{{ $row['new'] }}</td><td>{{ $row['visits'] }}</td>@foreach($row['methods'] as $count)<td>{{ $count }}</td>@endforeach</tr>@endforeach<tr class="total"><td>Total periode</td><td>{{ $summary['unique'] }}</td><td>{{ $summary['new'] }}</td><td>{{ $summary['visits'] }}</td>@foreach(range(0,6) as $i)<td>{{ array_sum(array_map(fn($row)=>$row['methods'][$i],$rows)) }}</td>@endforeach</tr></tbody></table><p class="footer">Peserta unik total periode dihitung ulang dan bukan penjumlahan peserta bulanan. Kolom metode menghitung jumlah pelayanan. Peserta baru dihitung pada pelayanan pertama yang sesuai filter.<br>Wilayah mengikuti wilayah peserta saat ini. Laporan agregat untuk penggunaan internal.</p></body></html>
